async def act(page):
    import re
    import asyncio

    product_name = "Minerva LumaTech V-Tee"

    # There are no knowledge-base helper functions available; none are used.

    # Heuristic: the Name filter textbox in the product grid is the 5th textbox on the page
    # (0-based index 4). Fill it with the product name and click the Search button located
    # inside the cell named "Reset Filter Search" to apply the grid filter.
    try:
        await page.get_by_role("textbox").nth(4).fill(product_name)
    except Exception:
        # Fallback: try the group-level Search textbox (top-left) if the heuristic fails
        try:
            await page.get_by_role("group", name="Search").get_by_role("textbox").fill(product_name)
        except Exception:
            # As a last resort, fill the first textbox on the page
            await page.get_by_role("textbox").first.fill(product_name)

    # Click the Search button in the filter area (use full path via the Reset Filter Search cell)
    try:
        await page.get_by_role("cell", name="Reset Filter Search").get_by_role("button", name="Search").click()
    except Exception:
        await page.get_by_role("button", name="Search").click()

    await page.wait_for_load_state("networkidle")
    await asyncio.sleep(0.6)

    # Find the results row containing our product and click its Edit link (scope to the row)
    found = False
    rows = page.get_by_role("row")
    count = await rows.count()
    for i in range(count):
        try:
            text = (await rows.nth(i).inner_text()) or ""
        except Exception:
            text = ""
        if re.search(re.escape(product_name), text, re.IGNORECASE):
            # Click the Edit link inside the matched row (use scoped get_by_role to avoid ambiguity)
            try:
                await rows.nth(i).get_by_role("link", name="Edit").click()
            except Exception:
                # If the Edit link isn't labeled exactly, click the first link in the row as fallback
                links = rows.nth(i).get_by_role("link")
                lcount = await links.count()
                if lcount:
                    await links.nth(0).click()
                else:
                    raise
            await page.wait_for_load_state("networkidle")
            found = True
            break

    if not found:
        # If the product was not found in the filtered results, raise so the failure is visible
        raise Exception(f'Could not locate product "{product_name}" in the product grid')

    # On the product edit page: open the Custom Options tab (try tab, then link, then button)
    await asyncio.sleep(0.6)
    opened_custom = False
    for role_kind in ("tab", "link", "button"):
        try:
            await page.get_by_role(role_kind, name="Custom Options").click()
            opened_custom = True
            break
        except Exception:
            continue
    if not opened_custom:
        raise Exception('Could not open the Custom Options tab for the product')

    await asyncio.sleep(0.6)

    # Click Add New Option (try common button names, then fall back to any Add button)
    add_clicked = False
    for label in ("Add New Option", "Add Option", "Add New Option +", "Add New Option+", "Add"):
        try:
            await page.get_by_role("button", name=label).click()
            add_clicked = True
            break
        except Exception:
            continue

    if not add_clicked:
        # fallback: click the first button whose inner text contains 'Add'
        try:
            btns = page.get_by_role("button")
            bcount = await btns.count()
            for i in range(bcount):
                try:
                    t = (await btns.nth(i).inner_text()) or ""
                except Exception:
                    t = ""
                if 'Add' in t:
                    await btns.nth(i).click()
                    add_clicked = True
                    break
        except Exception:
            pass

    await asyncio.sleep(0.6)

    # Fill the new option title as 'Size' and set its type to 'Drop-down'
    try:
        title_boxes = page.get_by_role("textbox", name="Title")
        tcount = await title_boxes.count()
        if tcount > 0:
            # Fill the last Title textbox (new option usually appends at the end)
            await title_boxes.nth(tcount - 1).fill("Size")
        else:
            # fallback: fill the last textbox on the page
            all_txt = page.get_by_role("textbox")
            total = await all_txt.count()
            if total > 0:
                await all_txt.nth(total - 1).fill("Size")
    except Exception:
        # Continue even if setting the title fails so visible failure happens on save
        pass

    try:
        type_boxes = page.get_by_role("combobox", name="Type")
        type_count = await type_boxes.count()
        if type_count > 0:
            await type_boxes.nth(type_count - 1).select_option(label="Drop-down")
        else:
            await page.get_by_role("combobox").first.select_option(label="Drop-down")
    except Exception:
        # ignore if Type combobox not found
        pass

    await asyncio.sleep(0.5)

    # Add the option value 'XXXL' by filling a suitable Title textbox (last available)
    try:
